import{_ as i,c as s,o as e,a3 as t}from"./chunks/framework.BusRvirq.js";const k=JSON.parse('{"title":"SyncETA 퀵스타트 가이드","description":"SyncETA 데스크톱 애플리케이션 설치(1분) 또는 Docker 온프레미스 서버 구동을 통해 첫 번째 시나리오를 녹화하고 실행하는 빠른 시작 가이드입니다.","frontmatter":{"title":"SyncETA 퀵스타트 가이드","description":"SyncETA 데스크톱 애플리케이션 설치(1분) 또는 Docker 온프레미스 서버 구동을 통해 첫 번째 시나리오를 녹화하고 실행하는 빠른 시작 가이드입니다.","head":[["meta",{"name":"keywords","content":"SyncETA 퀵스타트, 테스트 자동화 시작하기, 데스크톱 앱 다운로드, Playwright 테스트, 녹화 및 실행, Docker 배포"}],["meta",{"property":"og:title","content":"SyncETA 퀵스타트 가이드 | 엠파시(Empasy)"}],["meta",{"property":"og:description","content":"데스크톱 앱 설치 또는 Docker 배포를 통해 3분 만에 첫 웹 회귀 테스트를 실행합니다."}],["link",{"rel":"canonical","href":"https://doc.empasy.com/synceta/quickstart.html"}]],"sort":30},"headers":[],"relativePath":"synceta/quickstart.md","filePath":"ko/synceta/quickstart.md","lastUpdated":1789483631000}'),l={name:"synceta/quickstart.md"};function n(r,a,o,h,c,d){return e(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="synceta-퀵스타트-가이드" tabindex="-1">SyncETA 퀵스타트 가이드 <a class="header-anchor" href="#synceta-퀵스타트-가이드" aria-label="Permalink to “SyncETA 퀵스타트 가이드”">​</a></h1><p>SyncETA는 두 가지 방식으로 시작할 수 있습니다. 로컬 및 스테이징 환경에서 빠르게 테스트를 체험하고자 하는 경우 <strong>[방법 1: 데스크톱 앱 간편 설치]</strong>를, 팀 단위 중앙 관제 및 CI/CD 연동 서버를 구성하고자 하는 경우 <strong>[방법 2: Docker 기반 온프레미스 구축]</strong>을 선택하십시오.</p><hr><h2 id="방법-1-데스크톱-앱-간편-설치-권장-1분-시작" tabindex="-1">방법 1: 데스크톱 앱 간편 설치 (권장 - 1분 시작) <a class="header-anchor" href="#방법-1-데스크톱-앱-간편-설치-권장-1분-시작" aria-label="Permalink to “방법 1: 데스크톱 앱 간편 설치 (권장 - 1분 시작)”">​</a></h2><p>데스크톱 앱은 별도의 서버 구축이나 데이터베이스 설정 없이, 운영체제별 설치 파일 실행만으로 즉시 구동됩니다.</p><h3 id="_1단계-설치-파일-다운로드" tabindex="-1">1단계: 설치 파일 다운로드 <a class="header-anchor" href="#_1단계-설치-파일-다운로드" aria-label="Permalink to “1단계: 설치 파일 다운로드”">​</a></h3><p><a href="https://empasy.io/ko/download_eta.html" target="_blank" rel="noreferrer">엠파시 공식 다운로드 페이지(empasy.io)</a>에서 사용 중인 OS에 맞는 최신 안정화 빌드(v0.0.33)를 내려받습니다.</p><ul><li><strong>Windows</strong>: <code>SyncETA Setup 0.0.33.exe</code> (x64 및 arm64 지원)</li><li><strong>macOS</strong>: <code>SyncETA-0.0.33-arm64.dmg</code> (Apple Silicon M시리즈) 또는 <code>SyncETA-0.0.33.dmg</code> (Intel)</li></ul><h3 id="_2단계-애플리케이션-실행" tabindex="-1">2단계: 애플리케이션 실행 <a class="header-anchor" href="#_2단계-애플리케이션-실행" aria-label="Permalink to “2단계: 애플리케이션 실행”">​</a></h3><p>설치 완료 후 바탕화면 또는 애플리케이션 목록에서 <strong>SyncETA</strong>를 실행합니다. 별도의 로그인이나 외부 네트워크 인증 없이 로컬 모드로 즉시 기동됩니다.</p><hr><h2 id="방법-2-docker-compose-기반-온프레미스-구축-엔터프라이즈" tabindex="-1">방법 2: Docker Compose 기반 온프레미스 구축 (엔터프라이즈) <a class="header-anchor" href="#방법-2-docker-compose-기반-온프레미스-구축-엔터프라이즈" aria-label="Permalink to “방법 2: Docker Compose 기반 온프레미스 구축 (엔터프라이즈)”">​</a></h2><p>사내 인프라에 SyncETA 중앙 서버 및 Playwright 분산 실행 노드를 배포하는 방식입니다.</p><div class="language-bash"><button title="Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 저장소 클론 및 디렉토리 이동</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/DramaticCollaboration/SyncSeries.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SyncSeries/SyncEta</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 컨테이너 서비스 일괄 실행</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.dev.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>서비스 기동 후 브라우저에서 <code>http://localhost:9000</code>으로 접속하여 웹 콘솔에 접근합니다.</p><hr><h2 id="첫-번째-테스트-시나리오-녹화-및-실행-실습" tabindex="-1">첫 번째 테스트 시나리오 녹화 및 실행 실습 <a class="header-anchor" href="#첫-번째-테스트-시나리오-녹화-및-실행-실습" aria-label="Permalink to “첫 번째 테스트 시나리오 녹화 및 실행 실습”">​</a></h2><p>데스크톱 앱 또는 웹 콘솔 구동 후, 아래 4단계 절차를 통해 첫 회귀 테스트를 생성하고 실행합니다.</p><h3 id="_1단계-프로젝트-생성-및-기준-url-등록" tabindex="-1">1단계: 프로젝트 생성 및 기준 URL 등록 <a class="header-anchor" href="#_1단계-프로젝트-생성-및-기준-url-등록" aria-label="Permalink to “1단계: 프로젝트 생성 및 기준 URL 등록”">​</a></h3><ol><li>좌측 네비게이션에서 <strong>&#39;프로젝트&#39;</strong>를 클릭합니다.</li><li>우측 상단의 <strong>&#39;새 프로젝트&#39;</strong> 버튼을 누르고, 프로젝트 이름(예: <code>커머스 메인 플로우</code>)과 시작 URL(예: <code>https://shop.example.com</code> 또는 <code>http://localhost:3000</code>)을 입력합니다.</li></ol><h3 id="_2단계-사용자-인터랙션-녹화" tabindex="-1">2단계: 사용자 인터랙션 녹화 <a class="header-anchor" href="#_2단계-사용자-인터랙션-녹화" aria-label="Permalink to “2단계: 사용자 인터랙션 녹화”">​</a></h3><ol><li>좌측 메뉴에서 <strong>&#39;시나리오&#39;</strong> ➔ <strong>&#39;새로운 시나리오&#39;</strong>를 선택합니다.</li><li>대상 브라우저(Chromium) 및 뷰포트(1920x1080)를 지정한 뒤 <strong>&#39;녹화 시작&#39;</strong>을 클릭합니다.</li><li>생성된 브라우저 창에서 사용자 행동을 수행합니다: <ul><li>검색창 클릭 후 검색어 입력</li><li>검색 실행 버튼 클릭</li><li>검색 결과 목록에서 특정 항목 클릭</li></ul></li><li>녹화 제어 창에서 <strong>&#39;녹화 종료&#39;</strong>를 누르면 시나리오가 JSON/YAML 포맷으로 자동 정규화되어 저장됩니다.</li></ol><h3 id="_3단계-검증-조건-assertion-등록" tabindex="-1">3단계: 검증 조건(Assertion) 등록 <a class="header-anchor" href="#_3단계-검증-조건-assertion-등록" aria-label="Permalink to “3단계: 검증 조건(Assertion) 등록”">​</a></h3><ol><li>저장된 시나리오 편집기에서 검증할 마지막 스텝을 선택합니다.</li><li><strong>&#39;검증 조건 추가&#39; ➔ &#39;요소 노출 검증&#39;</strong>을 선택하고, 화면 내의 목표 컴포넌트(예: &#39;상세 정보&#39; 영역 또는 &#39;결제 버튼&#39;)를 지정합니다.</li></ol><h3 id="_4단계-playwright-엔진-무인-실행-및-자가-치유-검증" tabindex="-1">4단계: Playwright 엔진 무인 실행 및 자가 치유 검증 <a class="header-anchor" href="#_4단계-playwright-엔진-무인-실행-및-자가-치유-검증" aria-label="Permalink to “4단계: Playwright 엔진 무인 실행 및 자가 치유 검증”">​</a></h3><ol><li>우측 상단의 <strong>&#39;시나리오 실행&#39;</strong>을 클릭합니다.</li><li>실행 모드(헤드리스 또는 일반 브라우저)를 선택한 뒤 <strong>&#39;실행&#39;</strong>을 누릅니다.</li><li>실행 완료 후 대시보드에서 스텝별 성공 여부, 소요 시간, 캡처된 스크린샷 및 자가 치유(Self-Healing) 적용 내역을 검토합니다.</li></ol><hr><h2 id="다음-단계" tabindex="-1">다음 단계 <a class="header-anchor" href="#다음-단계" aria-label="Permalink to “다음 단계”">​</a></h2><ul><li><a href="./scenario-create">시나리오 녹화 및 에디터 상세 가이드</a> - 대기 조건, 복구 스크립트 설정</li><li><a href="./self-healing-and-vision">자가 치유 &amp; 비전 분석 원리</a> - Vision-LLM 기반 셀렉터 복구 메커니즘</li><li><a href="./dataset">데이터셋 관리</a> - Excel을 활용한 대량 파라미터 테스트</li><li><a href="./mcp-and-cicd">MCP 프로토콜 및 CI/CD 연동</a> - GitHub Actions 및 Jenkins 파이프라인 연동</li></ul>`,29)])])}const g=i(l,[["render",n]]);export{k as __pageData,g as default};
